(window.webpackJsonp=window.webpackJsonp||[]).push([[4],{50:function(e,n,t){"use strict";t.r(n);var a=t(0),i=t.n(a);n.default=function(){return i.a.createElement("div",null,i.a.createElement("p",null,"Picasso said that once a painting is finished, it's dead. I try to keep the painting alive. Painting is like breathing. To breathe is to live."),i.a.createElement("blockquote",null,"Where the spirit does not work with the hand there is no art"),i.a.createElement("blockquote",null,"**Leonardo da Vinci**"),i.a.createElement("p",null,"Historically, all the great masters have been men. I am interested in being unapologetic about being a woman, a mother, and an artist. Art is the highest form of hope. I paint to find hope."),i.a.createElement("p",null,"When I paint, it is an expression of confusion and entanglement, of being caught up in the mundanity of everyday life, but also a memory of something more. A throwing up onto the canvas of my thoughts wishes and desires."),i.a.createElement("p",null,"I am interested in finding beauty in unseen or forgotten things. I plaster memories onto a nursing home chair, because of my experience of my Nanna's decline."),i.a.createElement("p",null,"I tap into areas of my being that can only be expressed through spreading and mixing paint. Layering. I try to make the ugly beautiful and find gems in the rubble."),i.a.createElement("p",null,"> There's more gold in nature than we give credit for, because every day there are certain reflections where the sunrays hit and you get gold."),i.a.createElement("p",null,"> **Louise Nevelson (1899-1988)**"),"---",i.a.createElement("p",null,"Emma holds a first class Bachelor of Arts degree in Textile Design from Chelsea College of Art."),i.a.createElement("p",null,"She has exhibited in New York, Paris, Prague and Frankfurt. She was featured in International Textiles Magazine and also the Digital Textile Design book."))}}}]);